// A synchronous simulator of Node's loop ordering. No real timers/IO — pure arrays.
// Microtask queues (drained to empty between every macrotask):
const nextTickQ = [];   // process.nextTick — HIGHEST priority
const promiseQ  = [];   // promise reactions — drained after nextTickQ
// Macrotask phase queues (each is one phase, run in this order per tick):
const timersQ = [];     // timers phase  (setTimeout)
const pollQ   = [];      // poll phase    (I/O callbacks)
const checkQ  = [];     // check phase   (setImmediate)
const out = [];
const print = (s) => out.push(s);

// Schedulers a program would call:
const nextTick   = (label) => nextTickQ.push(label);
const microtask  = (label) => promiseQ.push(label);
const setTimeout0 = (label) => timersQ.push(label);
const onIO       = (label) => pollQ.push(label);
const setImmediate = (label) => checkQ.push(label);

// --- the "program" (synchronous body + scheduled callbacks) ---
print('SYNC1');
setTimeout0('TIMER0');
setImmediate('CHECK');
onIO('IO');
microtask('P1');
nextTick('NT1');
// P1's reaction itself schedules more work when it runs:
const afterP1 = () => { microtask('P2'); nextTick('NT2'); };
print('SYNC2');

// TODO: implement run(). It must:
//  1. drain BOTH microtask queues to empty (nextTickQ first, then promiseQ),
//     re-checking after each callback because callbacks can enqueue more;
//     when 'P1' runs, call afterP1() to enqueue P2 + NT2.
//  2. then process macrotask phases in order timers -> poll -> check,
//     draining microtasks to empty again after EACH macrotask.
//  3. print each label as it 'runs'.
function drainMicro() {
  // drain nextTickQ fully (higher priority), then promiseQ; repeat until both empty
  while (nextTickQ.length || promiseQ.length) {
    while (nextTickQ.length) print(nextTickQ.shift());
    if (promiseQ.length) {
      const label = promiseQ.shift();
      print(label);
      if (label === 'P1') afterP1();
    }
  }
}
function run() {
  drainMicro();
  for (const phase of [timersQ, pollQ, checkQ]) {
    while (phase.length) {
      print(phase.shift());
      drainMicro();
    }
  }
}

run();
console.log(out.join(' '));

