class LagMonitor {
  constructor(windowSize){ this.windowSize = windowSize; this.samples = []; this.last = 0; }
  record(lagMs){ this.samples.push(lagMs); if (this.samples.length > this.windowSize) this.samples.shift(); this.last = lagMs; }
  worstLag(){ return this.last; }
}

