// GET /report?id=...  — on the hot path
app.get('/report', (req, res) => {
  const raw = fs.readFileSync('./templates/report.html', 'utf8'); // load template
  const rows = db.queryRows(req.query.id);                        // returns an array, sync API
  let csv = '';
  for (const r of rows) {                                          // rows can be ~500k
    csv += r.id + ',' + r.name + ',' + r.total + '\n';
  }
  const hash = crypto.pbkdf2Sync(csv, 'salt', 600000, 32, 'sha256'); // integrity stamp
  res.send(raw.replace('{{csv}}', csv).replace('{{hash}}', hash.toString('hex')));
});
